import{_ as r,o,c as d,a3 as s}from"./chunks/framework.qCVWde4n.js";const p=JSON.parse('{"title":"这是什么","description":"","frontmatter":{},"headers":[],"relativePath":"what-is-afmod.md","filePath":"what-is-afmod.md","lastUpdated":1791133906000}'),a={name:"what-is-afmod.md"};function n(e,t,l,i,g,h){return o(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h1><h2 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h2><p><strong>大西洋舰队 Mod 框架</strong> 是给手机游戏《大西洋舰队》（Atlantic Fleet）用的。装上以后，改游戏不用连电脑。</p><p>它把原本「要手改文件、要连电脑、改错了游戏打不开」的 Mod 折腾，变成<strong>手机上点几下就能完成</strong>的事：拖滑块调数值、管理已装 Mod、改存档、看日志自查，全程不需要连电脑，也不需要懂 JSON。</p><p>无论你是想<strong>把主炮调强一点</strong>、<strong>加一艘自己画的船</strong>、<strong>让威望涨得快些</strong>，还是<strong>做一整套 Mod 分享给朋友</strong>，这个框架都能覆盖。</p><div class="tip custom-block"><p class="custom-block-title">它和「汉化」是两回事</p><p>它是基于汉化版《大西洋舰队》做的，但<strong>与汉化定版是相互隔离的两个包</strong>。汉化定版（<code>final_full_cn.apk</code>）保持原样不受影响；Mod 框架单独产出一个试装包 <code>final_full_cn_MOD_v1.apk</code>。装了 Mod 框架 = 汉化 + Mod 能力，不装就是纯汉化。</p></div><h2 id="mod-是什么-别想窄了" tabindex="-1">Mod 是什么（别想窄了） <a class="header-anchor" href="#mod-是什么-别想窄了" aria-label="Permalink to &quot;Mod 是什么（别想窄了）&quot;">​</a></h2><p><strong>Mod ≠ 改数值 + 加船。</strong> 任何装进这个框架、能改变游戏内容的作品都算 Mod：</p><table tabindex="0"><thead><tr><th>类别</th><th>你可以放什么</th></tr></thead><tbody><tr><td><strong>参数改装</strong></td><td>火力、鱼雷、传感器、经济、AI、航空的数值调整</td></tr><tr><td><strong>自定义舰船</strong></td><td>自己定义的舰级、武器、搭载</td></tr><tr><td><strong>自定义编队</strong></td><td>编队编制、阵型、出击规则</td></tr><tr><td><strong>模型 / 贴图</strong></td><td>3D 模型（AssetBundle）、涂装、图标等美术资源</td></tr><tr><td><strong>音频 / 语音</strong></td><td>音效、语音、背景音乐</td></tr><tr><td><strong>界面 / 皮肤</strong></td><td>界面配色、字体、图标、布局皮肤</td></tr><tr><td><strong>剧本 / 战役</strong></td><td>关卡、剧情、任务</td></tr><tr><td><strong>文本 / 翻译</strong></td><td>术语表、命名替换</td></tr><tr><td><strong>工具 / 脚本</strong></td><td>辅助工具、批量脚本</td></tr><tr><td><strong>整合包</strong></td><td>把上面几类打包成一键安装</td></tr></tbody></table><p>也就是说：<strong>别人做的舰船模型、贴图、音效、界面皮肤、战役剧本，都可以单独传上来分享</strong>，不必硬塞进&quot;改数值&quot;里。仓库页顶部有分类筛选，可以按类型找。</p><h2 id="它能做什么-框架提供的能力" tabindex="-1">它能做什么（框架提供的能力） <a class="header-anchor" href="#它能做什么-框架提供的能力" aria-label="Permalink to &quot;它能做什么（框架提供的能力）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>一句话说明</th></tr></thead><tbody><tr><td><strong>参数调节</strong></td><td>23 个参数，覆盖火力、鱼雷、传感器、经济、AI、航空。滑块直接拖</td></tr><tr><td><strong>自定义舰船</strong></td><td>定义自己的舰级、属性、武器、搭载，让原版没有的船出现</td></tr><tr><td><strong>自定义编队</strong></td><td>把任意舰船组进舰队，跨越原版的限制</td></tr><tr><td><strong>自制模型</strong></td><td>用自己的 3D 模型替换舰船外观（AssetBundle）</td></tr><tr><td><strong>游戏内控制台</strong></td><td>屏幕上一个小球，点开就是六个页面，全在手机里操作</td></tr><tr><td><strong>Mod 管理中心</strong></td><td>列出、禁用、启用、删除、分享，冲突自动检测</td></tr><tr><td><strong>存档编辑</strong></td><td>改当前战役的威望和回合，安全写盘</td></tr><tr><td><strong>诊断与日志</strong></td><td>日志落盘、三级分级、一键导出、状态探针</td></tr><tr><td><strong>Mod 分享仓库</strong></td><td>网页浏览、搜索、复制分享码、解析陌生分享码</td></tr><tr><td><strong>账号与分享</strong></td><td>分享码离线分发、本地热座对战</td></tr></tbody></table><h2 id="文档概览" tabindex="-1">文档概览 <a class="header-anchor" href="#文档概览" aria-label="Permalink to &quot;文档概览&quot;">​</a></h2><p>本文档分为以下几个部分：</p><ul><li><strong>开始</strong>。三分钟了解这是什么、怎么上手、内部是怎么实现的。</li><li><strong>安装部署</strong>。从下载 APK 到装好第一个 Mod 的完整路径，也包含从源码自己构建。</li><li><strong>功能接入</strong>。逐项讲清楚框架能改什么、怎么改、改完是什么效果。</li><li><strong>使用指南</strong>。游戏内控制台六个页面逐个说明，外加冲突排查、故障诊断、进阶组合玩法。</li><li><strong>开发</strong>。给 Mod 作者和想改框架本身的人：完整规范、参数键全表、AssetBundle 制作、发布流程。</li><li><strong>Mod 仓库</strong>。在线仓库的浏览、发布、运维三视角说明。</li><li><strong>帮助</strong>。常见问题、更新日志、路线图、术语表。</li></ul><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><p>三个入口，按你的情况选：</p><ul><li><strong>我只想调数值</strong> → 读 <a href="/AtlanticFleetSite/docs/deploy/">安装部署</a>，装好后直接进 <a href="/AtlanticFleetSite/docs/use/params-page">参数页</a>。</li><li><strong>我想装别人做的 Mod</strong> → 读 <a href="/AtlanticFleetSite/docs/deploy/install-mod">安装 Mod 的三种方式</a>，或直接去 <a href="/AtlanticFleetSite/docs/repo/browse">Mod 仓库</a>。</li><li><strong>我想自己做 Mod</strong> → 读 <a href="/AtlanticFleetSite/docs/dev/mod-json">mod.json 完整规范</a>，做完看 <a href="/AtlanticFleetSite/docs/dev/publish">发布到仓库</a>。</li></ul><h2 id="它是如何实现的" tabindex="-1">它是如何实现的 <a class="header-anchor" href="#它是如何实现的" aria-label="Permalink to &quot;它是如何实现的&quot;">​</a></h2><p>一句话：<strong>重新编译了整个游戏主程序，在关键位置挂上框架的钩子。</strong></p><p>游戏原本是 Unity 4.7 + Mono 编译出来的 <code>Assembly-CSharp.dll</code>。框架的做法是把它反编译还原成源码，在火力计算、模型加载、存档读写等位置插入请求转发，再重新编译回去。所以它不是一个外挂式的补丁，而是<strong>和游戏长在一起</strong>的改动 —— 这也是为什么它必须打包成完整 APK 而不是一个插件文件。</p><p>架构细节见 <a href="/AtlanticFleetSite/docs/architecture">它是如何实现的</a>。</p><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><ul><li>这是个人非商业项目，做给汉化和 Mod 爱好者交流用。</li><li>与游戏原开发商、发行商无关；请支持正版。</li><li>使用前请确认你已拥有《大西洋舰队》的合法副本。</li><li>框架对存档的改动<strong>只走游戏自带的存档接口</strong>，不直接改二进制存档文件。</li></ul>',24)])])}const u=r(a,[["render",n]]);export{p as __pageData,u as default};
